from pathlib import Path
r=Path(__file__).resolve().parent
p=r/'server/index.mjs'
s=p.read_text()
def replace(old,new):
 global s
 if s.count(old)!=1: raise SystemExit('Unexpected source for personal access patch')
 s=s.replace(old,new,1)
replace(' async function session(req){', ''' const personalExpiresAt=()=>Date.parse(env.PERSONAL_ACCESS_EXPIRES_AT);
 async function personalAvailable(){const issued=Date.parse(env.PERSONAL_ACCESS_ISSUED_AT),expires=personalExpiresAt();return live&&/^[a-f0-9]{64}$/.test(env.PERSONAL_ACCESS_HASH||'')&&Number.isFinite(issued)&&issued<=Date.now()&&expires>issued&&expires-issued<=86400000&&Date.now()<expires&&!(await store.query('SELECT token_hash FROM access_revocations WHERE token_hash=$1',[env.PERSONAL_ACCESS_HASH])).length;}
 async function session(req){''')
replace("if(s.user_id==='u5'&&(!await viewerAvailable()||!s.csrf.startsWith(env.VIEWER_ACCESS_HASH+'.')))return null;return s;", "if(s.user_id==='u5'&&(!await viewerAvailable()||!s.csrf.startsWith(env.VIEWER_ACCESS_HASH+'.')))return null;if(s.csrf.startsWith('personal.')&&(s.user_id!=='u0'||!await personalAvailable()||!s.csrf.startsWith('personal.'+env.PERSONAL_ACCESS_HASH+'.')))return null;return s;")
replace("[Date.now()+30*60000,s.token_hash]", "[s.csrf.startsWith('personal.')?Math.min(Date.now()+30*60000,personalExpiresAt()):Date.now()+30*60000,s.token_hash]")
replace("   if(p==='/viewer-access')", "   if(p==='/personal-access'||p==='/personal-access.js')return staticFile(res,path.join(ROOT,'site',p==='/personal-access'?'personal-access.html':'personal-access.js'));\n   if(p==='/viewer-access')")
replace("    if(p==='/auth/access'){", '''    if(p==='/auth/personal-access'){
     if(typeof b.token!=='string'||! /^[a-f0-9]{64}$/.test(b.token)||!await personalAvailable()||!timingSafeEqual(Buffer.from(hash(b.token),'hex'),Buffer.from(env.PERSONAL_ACCESS_HASH,'hex')))fail(403,'This personal link is invalid, expired, or revoked. Please use staff sign-in.');
     const t=token(),csrf='personal.'+env.PERSONAL_ACCESS_HASH+'.'+token();await store.transaction(async q=>{await q('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[sessionHash(t),'u0',Math.min(Date.now()+30*60000,personalExpiresAt()),csrf]);await audit(q,'u0','login.personal_link');});
     return json(res,200,{ok:true},{'Set-Cookie':`tl_session=${t}; Path=/; HttpOnly; SameSite=Strict${production?'; Secure':''}; Max-Age=1800`});
    }
    if(p==='/auth/access'){''')
replace("   if(p==='/api/admin/viewer-access'){", '''   if(p==='/api/admin/personal-access'){const a=await signedIn(req);if(a.user_id!=='u0')fail(403,'Account owner only.');if(req.method==='GET')return json(res,200,{active:!!await personalAvailable(),email:'steven@tharongroup.com',expiresAt:env.PERSONAL_ACCESS_EXPIRES_AT||null});if(req.method!=='DELETE')fail(405,'Use GET or DELETE.');if(env.PERSONAL_ACCESS_HASH)await store.transaction(async q=>{await q('INSERT INTO access_revocations (token_hash,revoked_at) VALUES ($1,$2) ON CONFLICT (token_hash) DO NOTHING',[env.PERSONAL_ACCESS_HASH,new Date().toISOString()]);await audit(q,a.user_id,'personal_access.revoked','u0');});return json(res,200,{ok:true});}
   if(p==='/api/admin/viewer-access'){''')
p.write_text(s)
(r/'site/personal-access.html').write_text((r/'site/access.html').read_text().replace('/access.js','/personal-access.js').replace('private admin access','personal access'))
(r/'site/personal-access.js').write_text("""(async function(){
'use strict';const accessToken=location.hash.slice(1);history.replaceState(null,'','/personal-access');const message=document.getElementById('accessMessage');
if(!accessToken){message.textContent='Open your full private link. If it has expired, use staff sign-in.';return;}
try{const response=await fetch('/auth/personal-access',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:accessToken})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to open this personal link.');location.replace('/');}catch(error){message.textContent=error.message;}
})();
""")

(r/'test/personal-access.test.mjs').write_text("import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';import {randomBytes,randomUUID,createHmac} from 'node:crypto';\nimport {createApplication} from '../server/index.mjs';import {hash} from '../server/security.mjs';\ntest('personal link opens Steven own admin session with live data, CSRF, attribution, expiry and immediate revocation',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),'tharon-access-')),access=randomBytes(32).toString('hex'),secret='private-access-test-secret';let expires=new Date(Date.now()+3600000).toISOString();\n const app=await createApplication({env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'state.sqlite'),SESSION_SECRET:secret,APP_ORIGIN:'',PERSONAL_ACCESS_ISSUED_AT:new Date(Date.now()-1000).toISOString(),PERSONAL_ACCESS_HASH:hash(access),PERSONAL_ACCESS_EXPIRES_AT:expires},schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n const post=(token,extra={})=>fetch(origin+'/auth/personal-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json',...extra},body:JSON.stringify({token})});\n try{\n assert.equal((await fetch(origin+'/personal-access')).status,200);\n assert.equal((await fetch(origin+'/api/state')).status,401);\n assert.equal((await post('bad')).status,403);\n assert.equal((await post(access,{Origin:'https://untrusted.invalid'})).status,403);\n const login=await post(access);assert.equal(login.status,200);const cookie=login.headers.get('set-cookie').split(';')[0];assert.match(login.headers.get('set-cookie'),/HttpOnly/);\n const stateResponse=await fetch(origin+'/api/state',{headers:{Cookie:cookie}}),boot=await stateResponse.json();assert.equal(boot.state.me,'u0');assert.equal(boot.state.users.find(u=>u.id==='u0').role,'admin');assert.ok(boot.state.buildings.length>3);assert.ok(!JSON.stringify(boot).includes(access));\n const command={id:randomUUID(),op:'createLead',createdId:'L_private_test',args:[{first:'Fictional',last:'PrivateAccess',building:'hallmark',rep:'u2',payer:'CalAIM Community Supports'}]};\n const send=csrf=>fetch(origin+'/api/commands',{method:'POST',headers:{Origin:origin,Cookie:cookie,'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:JSON.stringify(command)});\n assert.equal((await send('bad')).status,403);assert.equal((await send(boot.csrf)).status,200);\n const record=(await app.store.query('SELECT user_id FROM audit_log WHERE action=$1 AND record_id=$2',['createLead','L_private_test']))[0];assert.equal(record.user_id,'u0');\n assert.equal((await fetch(origin+'/api/users',{headers:{Cookie:cookie}})).status,200);\n const sessionToken='test-staff-session';await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update(sessionToken).digest('hex'),'u1',Date.now()+60000,'csrf']);assert.equal((await fetch(origin+'/api/admin/personal-access',{method:'DELETE',headers:{Origin:origin,Cookie:'tl_session='+sessionToken,'X-CSRF-Token':'csrf'}})).status,403);\n assert.equal((await fetch(origin+'/api/admin/personal-access',{method:'DELETE',headers:{Origin:origin,Cookie:cookie,'X-CSRF-Token':boot.csrf}})).status,200);\n assert.equal((await fetch(origin+'/api/state',{headers:{Cookie:cookie}})).status,401);assert.equal((await post(access)).status,403);\n assert.ok(!(await app.store.query('SELECT * FROM audit_log')).some(r=>JSON.stringify(r).includes(access)));\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n const expired=await createApplication({env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'expired.sqlite'),PERSONAL_ACCESS_ISSUED_AT:new Date(Date.now()-1000).toISOString(),PERSONAL_ACCESS_HASH:hash(access),PERSONAL_ACCESS_EXPIRES_AT:new Date(Date.now()-60000).toISOString()},schedule:false});await new Promise(r=>expired.server.listen(0,'127.0.0.1',r));const expiredOrigin='http://127.0.0.1:'+expired.server.address().port;try{assert.equal((await fetch(expiredOrigin+'/auth/personal-access',{method:'POST',headers:{Origin:expiredOrigin,'Content-Type':'application/json'},body:JSON.stringify({token:access})})).status,403);}finally{await expired.close();rmSync(dir,{recursive:true,force:true});}\n});\ntest('personal link duration is bounded and sessions expire without affecting password sessions',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),'personal-bounds-')),access=randomBytes(32).toString('hex'),secret='personal-bound-secret',now=Date.now(),realNow=Date.now;\n const env={NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'db'),APP_ORIGIN:'',SESSION_SECRET:secret,PERSONAL_ACCESS_HASH:hash(access),PERSONAL_ACCESS_ISSUED_AT:new Date(now).toISOString(),PERSONAL_ACCESS_EXPIRES_AT:new Date(now+60000).toISOString()};\n const app=await createApplication({env,schedule:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port;\n try{const login=await fetch(origin+'/auth/personal-access',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({token:access})});assert.equal(login.status,200);const cookie=login.headers.get('set-cookie').split(';')[0];\n const state=await(await fetch(origin+'/api/state',{headers:{Cookie:cookie}})).json();assert.equal(state.state.me,'u0');assert.ok(Number((await app.store.query('SELECT expires_at FROM sessions'))[0].expires_at)<=now+60000);\n await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update('normal-session').digest('hex'),'u0',now+300000,'normal-csrf']);\n Date.now=()=>now+60001;assert.equal((await fetch(origin+'/api/state',{headers:{Cookie:cookie}})).status,401);assert.equal((await fetch(origin+'/api/state',{headers:{Cookie:'tl_session=normal-session'}})).status,200);\n }finally{Date.now=realNow;await app.close();rmSync(dir,{recursive:true,force:true});}\n for(const issued of ['', 'invalid',new Date(now+60000).toISOString(),new Date(now-25*3600000).toISOString()]){const a=await createApplication({env:{...env,SQLITE_PATH:path.join(dir,'bounds'),PERSONAL_ACCESS_ISSUED_AT:issued},schedule:false});await new Promise(r=>a.server.listen(0,'127.0.0.1',r));const o='http://127.0.0.1:'+a.server.address().port;try{assert.equal((await fetch(o+'/auth/personal-access',{method:'POST',headers:{Origin:o,'Content-Type':'application/json'},body:JSON.stringify({token:access})})).status,403);}finally{await a.close();rmSync(dir,{recursive:true,force:true});}}\n});\n")
